import torch


def gen_inputs(ctx, device):
    shape = tuple(ctx["A__shape"])
    dtype = getattr(torch, ctx["A__dtype"])
    n = shape[-1]
    # Create a symmetric positive definite matrix: A = A @ A.T + I * n
    A = torch.randn(shape, dtype=dtype, device=device)
    A = A @ A.transpose(-2, -1) + torch.eye(n, dtype=dtype, device=device) * n
    return {"A": A}


def run(A, hermitian):
    return torch.linalg.ldl_factor(A, hermitian=hermitian)
